def f(gi,fill=2):
    H=len(gi);W=len(gi[0])
    # flood-fill background from border
    bg=Counter(v for row in gi for v in row).most_common(1)[0][0]
    seen=set(); q=deque()
    for i in range(H):
        for j in [0,W-1]:
            if gi[i][j]==bg and (i,j) not in seen: seen.add((i,j)); q.append((i,j))
    for j in range(W):
        for i in [0,H-1]:
            if gi[i][j]==bg and (i,j) not in seen: seen.add((i,j)); q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and gi[ni][nj]==bg and (ni,nj) not in seen:
                seen.add((ni,nj)); q.append((ni,nj))
    out=[row[:] for row in gi]
    for i in range(H):
        for j in range(W):
            if gi[i][j]==bg and (i,j) not in seen:
                out[i][j]=fill
    return out
