# Build dataset: one example per cell across ALL demos, features: boolean preds over markers & colors
def feats(gi,go):
    H,W=len(gi),len(gi[0])
    cnt=Counter(v for row in gi for v in row); nz=[c for c in cnt if c!=0]; mk=min(nz,key=lambda c:cnt[c])
    M={(i,j) for i in range(H) for j in range(W) if gi[i][j]==mk}
    out=[]
    for i in range(H):
        for j in range(W):
            v=gi[i][j]
            rmark=any(gi[i][jj]==mk for jj in range(W)); cmark=any(gi[ii][j]==mk for ii in range(H))
            # distance to nearest marker along each axis
            def near(di,dj):
                rr,cc=i+di,j+dj;n=0
                while 0<=rr<H and 0<=cc<W and (rr,cc) not in M:
                    n+=1; rr+=di; cc+=dj
                return n if (0<=rr<H and 0<=cc<W and (rr,cc) in M) else -1
            dU,dD,dL,dR=near(-1,0),near(1,0),near(0,-1),near(0,1)
            others=set()
            for di in (-1,0,1):
                for dj in (-1,0,1):
                    if di==0 and dj==0: continue
                    rr,cc=i+di,j+dj
                    while 0<=rr<H and 0<=cc<W:
                        if gi[rr][cc]!=mk and gi[rr][cc]!=0: others.add(gi[rr][cc])
                        rr+=di; cc+=dj
            out.append({
                'ismk':v==mk,'onrow':rmark,'oncol':cmark,
                'U>=3':dU>=3,'D>=3':dD>=3,'L>=3':dL>=3,'R>=3':dR>=3,
                'nearU':dU<=2,'nearD':dD<=2,'nearL':dL<=2,'nearR':dR<=2,
                'othercolors':tuple(sorted(others)),
                'val':v,'lab':go[i][j]
            })
    return out

