# Decision tree: find split that separates labels
def solve(data):
    keys=['ismk','onrow','oncol','U>=3','D>=3','L>=3','R>=3',
          'nearU','nearD','nearL','nearR','othercolors']
    bad=[]
    for kname in keys:
        vals=[e[kname] for e in data]
        if len(set(vals))==1:
            # constant feature, can't separate by itself unless single-valued
            pass
        tab=defaultdict(set)
        for e in data: tab[e[kname]][e['lab']].add(tuple(e['othercolors']))
        # does this feature alone separate?
        ok=True
        for vv,ssets in tab.items():
            if len(ssets)>1: ok=False; break
        if ok and kname not in ['othercolors']:
            return kname
    return None
